begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,email,aud,role) values ('a1000000-0000-4000-8000-000000000001','supplier-owner@example.invalid','authenticated','authenticated'),('a1000000-0000-4000-8000-000000000002','supplier-outsider@example.invalid','authenticated','authenticated');
insert into app.tenants(id,slug,name) values ('a2000000-0000-4000-8000-000000000001','supplier-test','Supplier test');
insert into app.tenant_memberships(tenant_id,user_id,status,is_owner) values ('a2000000-0000-4000-8000-000000000001','a1000000-0000-4000-8000-000000000001','active',true);
insert into app.locations(id,tenant_id,code,name) values ('a3000000-0000-4000-8000-000000000001','a2000000-0000-4000-8000-000000000001','MAIN','Main');
insert into app.suppliers(id,tenant_id,name,created_by) values ('a4000000-0000-4000-8000-000000000001','a2000000-0000-4000-8000-000000000001','Original Supplier','a1000000-0000-4000-8000-000000000001');
insert into app.purchase_orders(id,tenant_id,supplier_id,location_id,order_number,created_by) values ('a5000000-0000-4000-8000-000000000001','a2000000-0000-4000-8000-000000000001','a4000000-0000-4000-8000-000000000001','a3000000-0000-4000-8000-000000000001','PO-1','a1000000-0000-4000-8000-000000000001');
select throws_ok($$select app.update_supplier('a1000000-0000-4000-8000-000000000002','a2000000-0000-4000-8000-000000000001','a4000000-0000-4000-8000-000000000001',1,'Changed',null,null,null,false,'supplier-denied-0001','test')$$,'HCS30',null,'nonmember cannot edit');
create temp table updated as select app.update_supplier('a1000000-0000-4000-8000-000000000001','a2000000-0000-4000-8000-000000000001','a4000000-0000-4000-8000-000000000001',1,'Renamed Supplier',null,null,null,false,'supplier-update-0001','test') result;
select is((select supplier_name_snapshot from app.purchase_orders where id='a5000000-0000-4000-8000-000000000001'),'Original Supplier','order snapshot survives supplier rename');
select is(app.list_purchasing_context('a1000000-0000-4000-8000-000000000001','a2000000-0000-4000-8000-000000000001')->'orders'->0->>'supplierName','Original Supplier','history uses original snapshot');
select is(app.update_supplier('a1000000-0000-4000-8000-000000000001','a2000000-0000-4000-8000-000000000001','a4000000-0000-4000-8000-000000000001',1,'Renamed Supplier',null,null,null,false,'supplier-update-0001','test'),(select result from updated),'same-key replay is stable');
select throws_ok($$select app.update_supplier('a1000000-0000-4000-8000-000000000001','a2000000-0000-4000-8000-000000000001','a4000000-0000-4000-8000-000000000001',1,'Other',null,null,null,false,'supplier-stale-00001','test')$$,'HCS35',null,'stale revision rejected');
select app.update_supplier('a1000000-0000-4000-8000-000000000001','a2000000-0000-4000-8000-000000000001','a4000000-0000-4000-8000-000000000001',2,'Renamed Supplier',null,null,null,true,'supplier-archive-001','test');
select is((select count(*)::integer from app.purchase_orders where supplier_id='a4000000-0000-4000-8000-000000000001'),1,'archive preserves order');
select throws_ok($$insert into app.purchase_orders(tenant_id,supplier_id,location_id,order_number,created_by) values ('a2000000-0000-4000-8000-000000000001','a4000000-0000-4000-8000-000000000001','a3000000-0000-4000-8000-000000000001','PO-2','a1000000-0000-4000-8000-000000000001')$$,'HCS34',null,'archived supplier cannot start new order');
select * from finish();rollback;
